import { test, expect } from '@playwright/test';

test.describe('Error Clearing on Input Correction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should clear error message when invalid input is corrected', async ({ page }) => {
    // Locate and fill with invalid email
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    // Verify error message appears
    const errorMessage = page.getByText('Please enter a valid email address');
    await expect(errorMessage).toBeVisible();

    // Verify error state is applied to input
    await expect(emailInput).toHaveAttribute('data-error');

    // Correct the invalid input
    await emailInput.fill('valid.user@example.com');

    // Verify error message is cleared
    await expect(errorMessage).not.toBeVisible();

    // Verify error state is removed from input
    await expect(emailInput).not.toHaveAttribute('data-error');

    // Verify input value is correct
    await expect(emailInput).toHaveValue('valid.user@example.com');
  });

  test('should clear error when user deletes all invalid characters', async ({ page }) => {
    // Locate and fill with invalid phone number
    const phoneInput = page.getByLabel('Phone Number');
    await phoneInput.fill('123-invalid');

    // Verify error message appears
    const errorMessage = page.getByText('Please enter a valid phone number');
    await expect(errorMessage).toBeVisible();

    // Verify error state is applied to input
    await expect(phoneInput).toHaveAttribute('data-error');

    // Clear all invalid characters by deleting
    await phoneInput.press('Backspace');
    await phoneInput.press('Backspace');
    await phoneInput.press('Backspace');
    await phoneInput.press('Backspace');
    await phoneInput.press('Backspace');

    // Verify error message is cleared
    await expect(errorMessage).not.toBeVisible();

    // Verify error state is removed from input
    await expect(phoneInput).not.toHaveAttribute('data-error');

    // Verify input is empty
    await expect(phoneInput).toHaveValue('');
  });
});
